  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Niraparib, a basic piperidine-containing heteroaromatic drug, has an absolute oral bioavailability of approximately 73% in cancer patients, directly supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Flecainide, a basic amine aromatic drug, shows an absolute oral bioavailability of 70% in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Naratriptan, a basic amine heteroaromatic drug, has an oral bioavailability of 63% in men, well above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Sertindole, a piperidine-containing heteroaromatic drug, has an oral bioavailability of approximately 74%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Risdiplam, a basic heteroaromatic drug, has high oral bioavailability due to complete absorption and negligible first-pass extraction, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Didanosine has low absolute oral bioavailability (19% in children), but this is driven by acid lability and first-pass metabolism, features not shared by the query's stable basic fused heterocycle; this contradictory evidence is outweighed by the high-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer experimental evidence from basic amine/heteroaromatic drugs (niraparib, flecainide, naratriptan, sertindole, risdiplam) shows oral bioavailability well above 20%, outweighing the low-F nucleoside didanosine whose mechanism is not applicable. Prediction: high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "Human pharmacokinetic data for the query are absent.",
    "Metabolic stability and transporter-mediated absorption/efflux of the query are uncharacterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

